/**
 * Initialize the block filter.
 *
 * @param {Array} hiddenBlocks Array of block names to hide
 */
export const init = (hiddenBlocks) => {
    // If no hidden blocks, nothing to do.
    if (!hiddenBlocks || hiddenBlocks.length === 0) {
        return;
    }

    // Debug: Log what we're hiding.
    // eslint-disable-next-line no-console
    console.log('Plugin Visibility: Hiding blocks:', hiddenBlocks);

    // Function to hide blocks.
    const hideBlocks = () => {
        let hiddenCount = 0;

        // First, log all available blocks in the modal for debugging.
        const allBlocks = document.querySelectorAll('a.list-group-item[data-blockname]');
        // eslint-disable-next-line no-console
        console.log(`Plugin Visibility: Total blocks in modal: ${allBlocks.length}`);
        
        hiddenBlocks.forEach(blockName => {
            // Find all block options with this block name.
            const selector = `a.list-group-item[data-blockname="${blockName}"]`;
            // eslint-disable-next-line no-console
            console.log(`Plugin Visibility: Looking for block with selector: ${selector}`);
            
            const options = document.querySelectorAll(selector);

            // eslint-disable-next-line no-console
            console.log(`Plugin Visibility: Found ${options.length} instances of block "${blockName}"`);

            if (options.length === 0) {
                // If not found, log what blocks ARE available.
                // eslint-disable-next-line no-console
                console.log(`Plugin Visibility: Block "${blockName}" not found. Available blocks:`, 
                    Array.from(allBlocks).map(b => b.getAttribute('data-blockname')));
            }

            options.forEach(option => {
                // Hide the option.
                option.style.display = 'none';
                // Also mark it as hidden for accessibility.
                option.setAttribute('aria-hidden', 'true');
                hiddenCount++;
                // eslint-disable-next-line no-console
                console.log(`Plugin Visibility: Hidden block "${blockName}"`, option);
            });
        });

        // eslint-disable-next-line no-console
        console.log(`Plugin Visibility: Hidden ${hiddenCount} block options`);
    };

    // Function to wait for modal content to be loaded, then hide blocks.
    const waitForModalContent = (modalContainer) => {
        // Check if the blocks are already loaded.
        const checkAndHide = () => {
            const blockList = modalContainer.querySelector('.list-group');
            if (blockList && blockList.children.length > 0) {
                // eslint-disable-next-line no-console
                console.log('Plugin Visibility: Block modal content loaded, hiding blocks');
                hideBlocks();
                return true;
            }
            return false;
        };

        // Try immediately.
        if (checkAndHide()) {
            return;
        }

        // If not loaded yet, observe for changes.
        const contentObserver = new MutationObserver(() => {
            if (checkAndHide()) {
                contentObserver.disconnect();
            }
        });

        // Observe the modal for content changes.
        contentObserver.observe(modalContainer, {
            childList: true,
            subtree: true,
        });

        // Also try after short delays as fallback.
        setTimeout(() => {
            checkAndHide();
        }, 100);

        setTimeout(() => {
            checkAndHide();
        }, 500);
    };

    // Function to check if this is the block modal.
    const isBlockModal = (modalContainer) => {
        // Check for modal title "Add a block".
        const title = modalContainer.querySelector('[data-region="title"]');
        if (title && title.textContent.trim().toLowerCase().includes('add a block')) {
            return true;
        }
        // Alternative: check for .list-group with block items.
        const blockList = modalContainer.querySelector('.list-group a[data-blockname]');
        return !!blockList;
    };

    // Wait for the modal to be shown, then hide blocks.
    const observer = new MutationObserver((mutations) => {
        mutations.forEach((mutation) => {
            mutation.addedNodes.forEach((node) => {
                if (node.nodeType === 1) { // Element node.
                    let modalContainer = null;

                    // Check if this is the modal or contains the modal.
                    if (node.matches && node.matches('.modal[data-region="modal-container"]')) {
                        modalContainer = node;
                    } else if (node.querySelector) {
                        modalContainer = node.querySelector('.modal[data-region="modal-container"]');
                    }

                    if (modalContainer && isBlockModal(modalContainer)) {
                        // eslint-disable-next-line no-console
                        console.log('Plugin Visibility: Add block modal detected');
                        waitForModalContent(modalContainer);
                    }
                }
            });
        });
    });

    // Observe the body for modal additions.
    observer.observe(document.body, {
        childList: true,
        subtree: true,
    });

    // Also check if modal is already present on page load.
    const existingModals = document.querySelectorAll('.modal[data-region="modal-container"]');
    existingModals.forEach(modal => {
        if (isBlockModal(modal)) {
            // eslint-disable-next-line no-console
            console.log('Plugin Visibility: Existing block modal found on page load');
            waitForModalContent(modal);
        }
    });
};
